    // 前置：右栏收起（展开则点收起钮）
    if (await page.$('[data-testid="titlebar-collapse-workbench"]')) {
      await domClick('[data-testid="titlebar-collapse-workbench"]');
      await page.waitForSelector('[data-testid="titlebar-expand-workbench"]', { timeout: 10_000 });
    }
    const railBefore = await sampleRail();
    // 切一条非当前的历史会话
    const switched = await page.evaluate(`(() => {
      const rows = [...document.querySelectorAll('[data-session-id]')];
      const target = rows.find((row) => row.getAttribute('aria-current') !== 'true');
      if (!target) return null;
      const id = target.getAttribute('data-session-id');
      target.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      return id;
    })()`) as string | null;
    report.railRegression = { precondition: railBefore, switchedTo: switched };
    if (switched) {
      await delay(1_800);
      const railAfter = await sampleRail();
      (report.railRegression as Record<string, unknown>).afterSwitch = railAfter;
      (report.railRegression as Record<string, unknown>).stayedCollapsed = railAfter.collapsed === true;
      await page.screenshot({ path: path.join(out, `02-rail-after-session-switch-${tag}.png`) });
    }

    // ---- ② 窄态对齐：逐级压窄，定性「这是什么态」+ 逐宽量测 ----
    // 定性结论（修前复现）：窗口 <1180 侧栏自动收起（SIDEBAR_AUTO_COLLAPSE_WIDTH），
    // 手动再展开后 rail w-60 无下限——窗口 <240 时 rail 被 flex 压到窗口宽（爸截图 ~120px 即此态）。
    // 所以每档压窄后要手动点展开钮「到达被测状态」，并断言 rail 确实 <240。
    const narrowRuns: Array<Record<string, unknown>> = [];
    for (const width of [240, 200, 160]) {
      await page.setViewportSize({ width, height: 900 });
      await delay(500);
      if (await page.$('[data-testid="titlebar-expand-sidebar"]')) {
        await domClick('[data-testid="titlebar-expand-sidebar"]');
        await page.waitForSelector('[data-testid="sidebar-capability-zone"]', { timeout: 10_000 });
        await delay(400);
      }
      const m = await page.evaluate(`(() => {
        ${RECT_FN}
        const sidebar = document.querySelector('[data-testid="sidebar-collapse"]');
        const rail = sidebar ? sidebar.closest('.w-60') : null;
        const rowInfo = (row) => {
          if (!row) return null;
          const icon = row.querySelector('svg');
          const title = row.querySelector('span.truncate');
          const bits = [...row.querySelectorAll('span')].map((s) => ({
            text: (s.textContent ?? '').trim().slice(0, 24),
            rect: __rect(s),
            truncated: s.classList.contains('truncate') ? s.scrollWidth > s.clientWidth : null,
          }));
          return {
            row: __rect(row),
            iconLeft: icon ? icon.getBoundingClientRect().left : null,
            titleTruncated: title ? title.scrollWidth > title.clientWidth : null,
            titleText: title ? (title.textContent ?? '').slice(0, 30) : null,
            spans: bits,
          };
        };
        const automation = document.querySelector('[data-testid="sidebar-capability-automation"]');
        const group = document.querySelector('[data-sidebar-group-phase]');
        const groupHeader = group ? group.firstElementChild : null;
        const sessionRow = document.querySelector('[data-session-id]');
        return {
          viewportWidth: window.innerWidth,
          rail: __rect(rail),
          reachedSqueezedState: rail ? rail.getBoundingClientRect().width < 240 : false,
          automationRow: rowInfo(automation),
          groupHeader: rowInfo(groupHeader),
          sessionRow: rowInfo(sessionRow),
          horizontalScroll: rail ? rail.scrollWidth > rail.clientWidth : null,
        };
      })()`) as Record<string, unknown>;
      narrowRuns.push(m);
      await page.screenshot({ path: path.join(out, `03-narrow-${width}-${tag}.png`) });
    }
    report.narrow = narrowRuns;
    await page.setViewportSize({ width: 1440, height: 900 });
    await delay(500);
    // 窄窗自动收起是单向的，回 1440 后侧栏仍收着——先展开再进空间页（此前探针在 ④ 扑空的原因）
    if (await page.$('[data-testid="titlebar-expand-sidebar"]')) {
      await domClick('[data-testid="titlebar-expand-sidebar"]');
      await page.waitForSelector('[data-testid="sidebar-capability-zone"]', { timeout: 10_000 });
      await delay(400);
    }

    // ---- ④准绳：能力中心「页头 ↔ 内容区」间距现值 ----
    await domClick('[data-testid="sidebar-capability-hub"]');
    await page.waitForSelector('nav[role="tablist"]', { timeout: 30_000 });
    await delay(600);
    const hubRhythm = await page.evaluate(`(() => {
      ${RECT_FN}
      const nav = [...document.querySelectorAll('header nav[role="tablist"]')][0] ?? null;
      const header = nav ? nav.closest('header') : null;
      const content = header ? header.nextElementSibling : null;
      const navRect = nav ? nav.getBoundingClientRect() : null;
      const contentRect = content ? content.getBoundingClientRect() : null;
      return {
        header: __rect(header),
        nav: __rect(nav),
        content: __rect(content),
        gapNavBottomToContentTop: navRect && contentRect ? contentRect.top - navRect.bottom : null,
      };
    })()`) as unknown;
    report.hubHeaderContentGap = hubRhythm;
    await page.screenshot({ path: path.join(out, `05-hub-header-content-${tag}.png`) });

    // ---- ④ 空间页头底 → tab 行顶 gap ----
    const projectApi = async <T = unknown>(action: string, payload?: unknown): Promise<T> => {
      const response = await fetch(`${base}/api/domain/project/${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ payload }),
      });
      const json = (await response.json()) as { success?: boolean; data?: T; error?: unknown };
      if (!json.success) throw new Error(`project/${action} failed: ${JSON.stringify(json.error)}`);
      return json.data as T;
    };
    interface SpaceRow { id: string; name: string; workspacePath?: string | null }
    const spaces = await projectApi<SpaceRow[]>('listWithActivity', { includeArchived: false, spacesOnly: true });
    let space = spaces.find((item) => item.workspacePath) ?? spaces[0];
    if (!space) {
      space = await projectApi<SpaceRow>('createSpace', { name: '探针空间⑤', workspacePath: process.cwd() });
    }
    report.space = { id: space.id, name: space.name };
    await domClick('[data-testid="sidebar-capability-projects"]');
    await page.waitForSelector('[data-testid="project-space-page"]', { timeout: 30_000 });
    await page.waitForSelector(`[data-testid="project-space-list-item-${space.id}"]`, { state: 'attached', timeout: 30_000 });
    await domClick(`[data-testid="project-space-list-item-${space.id}"]`);
    await page.waitForSelector('[data-testid="project-space-tab-activity"]', { timeout: 30_000 });
    await delay(600);
    const headerTabGap = await page.evaluate(`(() => {
      ${RECT_FN}
      const spacePage = document.querySelector('[data-testid="project-space-page"]');
      const header = spacePage ? spacePage.querySelector('header') : null;
      const nav = spacePage ? spacePage.querySelector('nav[role="tablist"]') : null;
      const firstTab = document.querySelector('[data-testid="project-space-tab-activity"]');
      const headerRect = header ? header.getBoundingClientRect() : null;
      const navRect = nav ? nav.getBoundingClientRect() : null;
      const firstTabRect = firstTab ? firstTab.getBoundingClientRect() : null;
      return {
        header: __rect(header),
        nav: __rect(nav),
        firstTab: __rect(firstTab),
        gapHeaderBottomToNavTop: headerRect && navRect ? navRect.top - headerRect.bottom : null,
        gapHeaderBottomToFirstTabTop: headerRect && firstTabRect ? firstTabRect.top - headerRect.bottom : null,
      };
    })()`) as unknown;
    report.spaceHeaderTabGap = headerTabGap;
    await page.screenshot({ path: path.join(out, `04-space-header-tab-${tag}.png`) });
  } finally {
    await writeFile(path.join(out, `report-${tag}.json`), JSON.stringify(report, null, 2));
    await browser.close();
  }

  console.log(JSON.stringify(report, null, 2));
}

main().catch((error) => {
  console.error('探针异常：', error);
  process.exit(1);
});
#!/usr/bin/env npx tsx
// ============================================================================
// Collaboration space context + space_create real-runtime acceptance.
//
// Uses an isolated data directory, a real Xiaomi model request, and the
// production AgentLoop/ToolExecutor/ProjectService path. An axios request
// interceptor inspects the serialized request body immediately before it is
// sent, without logging credentials or unrelated conversation content.
//
// Run:
//   env -u HTTPS_PROXY -u HTTP_PROXY npx tsx \
//     scripts/acceptance/space-context-tools-real-runtime.ts
// ============================================================================

import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
} from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';

function loadEnvIntoProcess(realHome: string): void {
  try {
    const envPath = join(realHome, '.code-agent', '.env');
    for (const raw of readFileSync(envPath, 'utf8').split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;
      const separator = line.indexOf('=');
      if (separator < 0) continue;
      const key = line.slice(0, separator).trim();
      let value = line.slice(separator + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"'))
        || (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (!process.env[key]) process.env[key] = value;
    }
  } catch {
    // A configured provider key is checked explicitly below.
  }
}

function extractSpaceContext(body: unknown): string | null {
  if (!body || typeof body !== 'object') return null;
  const messages = (body as { messages?: unknown }).messages;
  if (!Array.isArray(messages)) return null;
  const serialized = JSON.stringify(messages);
  const start = serialized.indexOf('<collaboration_space_context>');
  const endMarker = '</collaboration_space_context>';
  const end = serialized.indexOf(endMarker, start);
  if (start < 0 || end < 0) return null;
  return serialized.slice(start, end + endMarker.length).replaceAll('\\n', '\n');
}

async function main(): Promise<void> {
  const realHome = process.env.HOME || homedir();
  loadEnvIntoProcess(realHome);
  delete process.env.HTTPS_PROXY;
  delete process.env.HTTP_PROXY;
  delete process.env.https_proxy;
  delete process.env.http_proxy;

  const root = mkdtempSync(join(tmpdir(), 'space-real-runtime-'));
  const dataDir = join(root, 'data');
  const sourceWorkspace = join(root, 'source-workspace');
  const createdWorkspace = join(root, 'model-created-workspace');
  mkdirSync(dataDir, { recursive: true });
  mkdirSync(sourceWorkspace, { recursive: true });
  mkdirSync(createdWorkspace, { recursive: true });
  process.env.HOME = root;
  process.env.CODE_AGENT_HOME = root;
  process.env.CODE_AGENT_DATA_DIR = dataDir;
  process.env.CODE_AGENT_E2E = '1';
  process.env.CODE_AGENT_DISABLE_RECENT_CONVERSATIONS = 'true';
  const provider = process.env.SPACE_ACCEPTANCE_PROVIDER || 'deepseek';
  const model = process.env.SPACE_ACCEPTANCE_MODEL || 'deepseek-chat';

  const axios = (await import('axios')).default;
  const capturedBodies: unknown[] = [];
  const interceptorId = axios.interceptors.request.use((config) => {
    if (typeof config.data === 'string') {
      try {
        const parsed = JSON.parse(config.data) as unknown;
        if (parsed && typeof parsed === 'object' && Array.isArray((parsed as { messages?: unknown }).messages)) {
          capturedBodies.push(parsed);
        }
      } catch {
        // Ignore non-JSON requests.
      }
    }
    return config;
  });

  try {
    const { initializeCLIServices } = await import('../../src/cli/bootstrap');
    const { getConfigService } = await import('../../src/host/services/core/configService');
    const { getDatabase } = await import('../../src/host/services/core/databaseService');
    const { resolveSessionDefaultModelConfig } = await import('../../src/host/services/core/sessionDefaults');
    const { getProjectService } = await import('../../src/host/services/project/projectService');
    const { getProjectSkillPreferenceStore } = await import('../../src/host/services/skills/projectSkillPreferenceService');
    const { installBuiltinRoles } = await import('../../src/host/services/roleAssets');
    const { initAgentRegistry, disposeAgentRegistry } = await import('../../src/host/agent/agentRegistry');
    const { getCronService } = await import('../../src/host/cron/cronService');
    const { AgentLoop } = await import('../../src/host/agent/agentLoop');
    const { ToolExecutor } = await import('../../src/host/tools/toolExecutor');
    const { getAllToolDefinitions } = await import('../../src/host/tools/dispatch/toolDefinitions');
    const { SYSTEM_PROMPT } = await import('../../src/host/prompts/builder');
    const { evaluateFolderTrust } = await import('../../src/host/security/folderTrustService');
    const { estimateTokens } = await import('../../src/host/context/tokenEstimator');

    await initializeCLIServices({ dangerouslySkipPermissions: true });
    const database = getDatabase();
    await database.initialize();
    await installBuiltinRoles();
    await initAgentRegistry(sourceWorkspace);

    const modelConfig = resolveSessionDefaultModelConfig({ provider, model });
    const configuredKey = getConfigService().getApiKey(provider) || modelConfig.apiKey;
    if (!configuredKey) {
      throw new Error(`${provider}/${model} apiKey is not configured`);
    }

    const projectService = getProjectService();
    const now = Date.now();
    const sourceSpace = await projectService.createSpace({
      name: '真实验收上下文空间',
      description: '验证模型请求载荷中的空间配置',
      workspacePath: sourceWorkspace,
    }, now);
    projectService.addRole(sourceSpace.id, '数据分析师', now + 1);
    projectService.selectCapability(sourceSpace.id, 'connector', 'mail', now + 2);
    getProjectSkillPreferenceStore(sourceWorkspace).setOverride('data-analysis-helper', true);

    const cron = getCronService();
    await cron.initialize();
    await cron.createJob({
      name: '空间日报验收',
      description: 'real-runtime acceptance fixture',
      scheduleType: 'every',
      schedule: { type: 'every', interval: 1, unit: 'days' },
      action: {
        type: 'agent',
        agentType: 'general',
        prompt: '生成空间日报',
        libraryProjectId: sourceSpace.id,
      },
      enabled: false,
    });

    const workspaceScope = projectService.getWorkspaceScope(sourceSpace.id);
    if (!workspaceScope) throw new Error('source collaboration space has no workspace scope');

    const sessionId = `space-real-runtime-${now}`;
    const authorUserId = 'member-real-runtime';
    database.createSessionWithId(sessionId, {
      title: '协作空间真实验收',
      userId: 'owner-real-runtime',
      modelConfig: { provider: provider as 'deepseek', model },
      workingDirectory: sourceWorkspace,
      projectId: sourceSpace.id,
      type: 'chat',
    });
    database.addMessage(sessionId, {
      id: `author-${now}`,
      role: 'user',
      content: '准备创建另一个协作空间',
      timestamp: now,
    });
    database.getDb()?.prepare(
      'UPDATE messages SET author_user_id = ? WHERE id = ?',
    ).run(authorUserId, `author-${now}`);

    const targetName = `模型创建验收空间-${now}`;
    const prompt = [
      '请调用 space_create 工具创建一个新的协作空间。',
      `名称必须是：${targetName}`,
      '描述必须是：真实模型工具链验收',
      `workspacePath 必须是：${createdWorkspace}`,
      '必须实际调用工具，完成后只简短确认。',
    ].join('\n');
    const messages = [{
      id: `user-${now}`,
      role: 'user' as const,
      content: prompt,
      timestamp: now + 1,
    }];
    const toolCalls: Array<{ id: string; name: string; args: Record<string, unknown> }> = [];
    const toolResults: Array<{ name: string; success: boolean }> = [];
    const errors: string[] = [];
    const toolExecutor = new ToolExecutor({
      requestPermission: async () => true,
      workingDirectory: sourceWorkspace,
    });
    const deniedToolNames = getAllToolDefinitions()
      .map((definition) => definition.name)
      .filter((name) => name !== 'space_create');
    const loop = new AgentLoop({
      sessionId,
      workingDirectory: sourceWorkspace,
      projectConfigDirectory: sourceWorkspace,
      workspaceScope,
      systemPrompt: SYSTEM_PROMPT,
      modelConfig: {
        ...modelConfig,
        provider: provider as 'deepseek',
        model,
        apiKey: configuredKey,
        temperature: 0,
        reasoningEffort: 'low',
        maxTokens: 2048,
      },
      maxIterations: 5,
      enableToolDeferredLoading: false,
      deniedToolNames,
      autoApprovePlan: true,
      toolExecutor,
      messages,
      onEvent: (event) => {
        if (event.type === 'tool_call_start') {
          toolCalls.push({
            id: event.data.id,
            name: event.data.name,
            args: event.data.arguments || {},
          });
        } else if (event.type === 'tool_call_end') {
          const call = toolCalls.find((candidate) => candidate.id === event.data.toolCallId);
          toolResults.push({
            name: call?.name || 'unknown',
            success: event.data.success,
          });
        } else if (event.type === 'error') {
          errors.push(event.data?.message || 'unknown runtime error');
        }
      },
    });

    await loop.run(prompt);

    const contextBlock = capturedBodies
      .map(extractSpaceContext)
      .find((candidate): candidate is string => Boolean(candidate));
    if (!contextBlock) throw new Error('actual model request did not contain collaboration space context');

    const expectedContextFragments = [
      `space_id: ${sourceSpace.id}`,
      'space_name: 真实验收上下文空间',
      'space_description: 验证模型请求载荷中的空间配置',
      `initiating_user_id: ${authorUserId}`,
      'selected_experts: 知微 · 数据分析师',
      'selected_skills: data-analysis-helper',
      'selected_connectors: mail',
      'selected_automations: 空间日报验收',
      'treat produced artifacts as belonging to this space',
    ];
    const missingFragments = expectedContextFragments.filter(
      (fragment) => !contextBlock.includes(fragment),
    );
    if (missingFragments.length > 0) {
      throw new Error(`actual request context is missing: ${missingFragments.join(' | ')}`);
    }

    const created = projectService.listProjectsWithActivity(false, true)
      .find((project) => project.name === targetName);
    const createCall = toolCalls.find((call) => call.name === 'space_create');
    const createSucceeded = toolResults.some(
      (result) => result.name === 'space_create' && result.success,
    );
    if (!createCall || !createSucceeded || !created) {
      throw new Error(
        `model space_create chain failed: called=${Boolean(createCall)} success=${createSucceeded} persisted=${Boolean(created)}`,
      );
    }
    const trust = await evaluateFolderTrust(createdWorkspace);
    if (trust.state !== 'trusted') {
      throw new Error(`model-created workspace is not trusted: ${trust.state}`);
    }

    console.log('=== REAL-RUNTIME PASS ===');
    console.log(`provider: ${provider}/${model}`);
    console.log(`captured model requests: ${capturedBodies.length}`);
    console.log(`context chars: ${contextBlock.length}`);
    console.log(`context estimated tokens: ${estimateTokens(contextBlock)}`);
    console.log('cache impact: dynamic-tail-only');
    console.log(`context fields verified: ${expectedContextFragments.length}/${expectedContextFragments.length}`);
    console.log(`tool sequence: ${toolCalls.map((call) => call.name).join(' -> ')}`);
    console.log(`space_create persisted: ${created.id}`);
    console.log(`workspace trust: ${trust.state}`);
    console.log(`runtime errors: ${errors.length}`);

    await cron.shutdown();
    await disposeAgentRegistry();
    database.close();
  } finally {
    axios.interceptors.request.eject(interceptorId);
    rmSync(root, { recursive: true, force: true });
  }
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error('REAL-RUNTIME FAIL:', error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
#!/usr/bin/env npx tsx
// ============================================================================
// 批P 第四波返工 ② headless 探针：正常会话右栏 workbench tab 条贴顶。
// 量测（真实渲染 getBoundingClientRect，不猜 padding）：
//   - tab 条（workbench-view-selector）top 与窗口顶的距离（贴顶 = 0）
//   - 收起/展开开关两态的纵向位置（房规：两态同位，top 差必须 ≤1px）
// 交互回归：开视图 → ＋弹层加视图 → tab 切换 → 关闭 tab → 收起 → 展开。
//
// 用法：
//   npx tsx scripts/acceptance/workbench-tabstrip-flush-probe.ts \
//     --base http://127.0.0.1:18186 --out /tmp/p4-probe [--tag before]
// ============================================================================

import { mkdir, writeFile } from 'fs/promises';
import path from 'path';
import { setTimeout as delay } from 'timers/promises';
import { loadPlaywrightChromium } from '../../src/host/agent/runtime/browser/playwrightRuntime';

function argValue(flag: string): string | null {
  const index = process.argv.indexOf(flag);
  return index >= 0 ? process.argv[index + 1] ?? null : null;
}

const RECT_FN = `function __rect(selector) {
  const el = document.querySelector(selector);
  if (!el) return null;
  const r = el.getBoundingClientRect();
  return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height };
}`;

async function main(): Promise<void> {
  const base = (argValue('--base') ?? 'http://127.0.0.1:18186').replace(/\/$/, '');
  const out = argValue('--out') ?? '/tmp/p4-probe';
  const tag = argValue('--tag') ?? 'run';
  await mkdir(out, { recursive: true });

  const pw = await loadPlaywrightChromium();
  if (!pw.ok || !pw.chromium) throw new Error(`playwright 不可用: ${pw.error ?? 'unknown'}`);
  const browser = await pw.chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('console', (msg) => {
    if (msg.type() === 'error') console.log(`[console.error] ${msg.text().slice(0, 300)}`);
  });

  const report: Record<string, unknown> = { base, tag, startedAt: new Date().toISOString() };
  const interactions: Array<Record<string, unknown>> = [];
  report.interactions = interactions;

  const domClick = async (selector: string): Promise<void> => {
    await page.evaluate((sel) => {
      const el = document.querySelector(sel);
      if (!(el instanceof HTMLElement)) throw new Error(`domClick: ${sel} 不存在`);
      el.click();
    }, selector);
  };

  try {
    await page.goto(base, { waitUntil: 'domcontentloaded' });
    await page.waitForSelector('[data-testid="sidebar-new-task"]', { timeout: 60_000 });
    const trustButton = await page.waitForSelector(
      'button:has-text("信任并加载"), button:has-text("Trust and load")',
      { timeout: 3_000 },
    ).catch(() => null);
    if (trustButton) {
      await trustButton.click();
      await page.waitForSelector(
        'button:has-text("信任并加载"), button:has-text("Trust and load")',
        { state: 'detached', timeout: 10_000 },
      ).catch(() => undefined);
    }
    await delay(2_000);

    // ---- 展开右栏（收起态先点展开钮） ----
    if (await page.$('[data-testid="titlebar-expand-workbench"]')) {
      await domClick('[data-testid="titlebar-expand-workbench"]');
      await page.waitForSelector('[data-testid="titlebar-collapse-workbench"]', { timeout: 10_000 });
    }
    // 空态 launcher → 开「文件」视图，让 tab 条出现
    await page.waitForSelector('[data-testid="open-workbench-view-files"]', { timeout: 10_000 });
    await domClick('[data-testid="open-workbench-view-files"]');
    await page.waitForSelector('[data-testid="workbench-view-selector"]', { timeout: 10_000 });
    interactions.push({ step: 'open files view', ok: true });

    // ---- 核心量测：tab 条距窗口顶 ----
    const flush = await page.evaluate(`(() => {
      ${RECT_FN}
      return {
        strip: __rect('[data-testid="workbench-view-selector"]'),
        rightPanel: __rect('[id="right-panel"]'),
        titleBar: __rect('[data-tauri-drag-region]'),
        collapseToggle: __rect('[data-testid="titlebar-collapse-workbench"]'),
      };
    })()`) as Record<string, { top: number } | null>;
    report.flushMeasure = {
      ...flush,
      stripGapToWindowTop: flush.strip?.top ?? null,
      stripVsRightPanelTopDelta: flush.strip && flush.rightPanel ? flush.strip.top - flush.rightPanel.top : null,
    };
    await page.screenshot({ path: path.join(out, `02-tabstrip-flush-${tag}.png`) });

    // ---- 交互回归 1：＋弹层加视图 ----
    await domClick('[data-testid="workbench-view-selector"] [aria-haspopup="true"]');
    await page.waitForSelector('[data-testid="workbench-view-menu"]', { timeout: 5_000 });
    await domClick('[data-testid="open-workbench-view-overview"]');
    await page.waitForSelector('[data-testid="workbench-tab-overview"]', { timeout: 5_000 });
    interactions.push({ step: 'plus menu add overview', ok: true });

    // ---- 交互回归 2：tab 切换 ----
    await domClick('[data-testid="workbench-tab-files"]');
    await delay(200);
    const filesSelected = await page.evaluate(
      `document.querySelector('[data-testid="workbench-tab-files"]')?.getAttribute('aria-selected')`,
    );
    interactions.push({ step: 'switch to files tab', ok: filesSelected === 'true', ariaSelected: filesSelected });

    // ---- 交互回归 3：关闭 overview tab ----
    await domClick('[data-testid="workbench-tab-overview"] button');
    await delay(300);
    const overviewGone = !(await page.$('[data-testid="workbench-tab-overview"]'));
    interactions.push({ step: 'close overview tab', ok: overviewGone });

    // ---- 交互回归 4+5：收起 → 展开（两态开关纵向同位量测） ----
    const toggleExpanded = await page.evaluate(`(() => {
      ${RECT_FN}
      return __rect('[data-testid="titlebar-collapse-workbench"]');
    })()`) as { top: number; left: number } | null;
