import { IconButton } from '../../primitives/IconButton';

export interface ProjectArtifactsListProps {
  projectId: string;
  /** 动态流跳入时要高亮的 artifact id（可选） */
  highlightId?: string | null;
  onOpenSession: (sessionId: string) => void;
}

function artifactDisplayName(artifact: ProjectArtifact): string {
  if (artifact.title?.trim()) return artifact.title.trim();
  if (artifact.path) {
    const segments = artifact.path.split(/[\\/]/).filter(Boolean);
    if (segments.length > 0) return segments[segments.length - 1];
  }
  return artifact.id;
}

export const ProjectArtifactsList: React.FC<ProjectArtifactsListProps> = ({
  projectId,
  highlightId = null,
  onOpenSession,
}) => {
  const { t } = useI18n();
  const ps = t.projectSpace;
  const [artifacts, setArtifacts] = useState<ProjectArtifact[] | null>(null);

  useEffect(() => {
    let cancelled = false;
    getProjectArtifacts(projectId)
      .then((list) => {
        if (!cancelled) setArtifacts(list);
      })
      .catch(() => {
        if (!cancelled) setArtifacts([]);
      });
    return () => {
      cancelled = true;
    };
  }, [projectId]);

  if (artifacts === null) {
    return <div className="py-10 text-center text-sm text-zinc-600">{t.common.loading}</div>;
  }

  if (artifacts.length === 0) {
    return <EmptyState variant="panel" icon={FileBox} text={ps.assetsEmpty} />;
  }

  return (
    <div className="grid gap-1" data-testid="project-space-assets-list">
      {artifacts.map((artifact) => (
        <div
          key={artifact.id}
          data-testid={`project-space-asset-${artifact.id}`}
          className={`group flex min-w-0 items-center gap-3 rounded-lg px-3 py-2 hover:bg-zinc-800/60 ${
            highlightId === artifact.id ? 'bg-zinc-800/70 ring-1 ring-violet-500/40' : ''
          }`}
        >
          <FileBox className="h-4 w-4 flex-shrink-0 text-zinc-500" />
          <span className="min-w-0 flex-1">
            <span className="block truncate text-sm text-zinc-300">{artifactDisplayName(artifact)}</span>
            {artifact.sessionTitle ? (
              <span className="mt-0.5 block truncate text-xs text-zinc-600">{artifact.sessionTitle}</span>
            ) : null}
          </span>
          <Badge className="flex-shrink-0 border-zinc-700 bg-zinc-800/60 text-[10px] text-zinc-400">{artifact.kind}</Badge>
          <span className="flex-shrink-0 text-[11px] text-zinc-600 tabular-nums">
            {formatRelativeTime(t, artifact.createdAt)}
          </span>
          {artifact.sessionId ? (
            <IconButton
              size="sm"
              variant="ghost"
              icon={<CornerUpRight className="h-3.5 w-3.5" />}
              aria-label={ps.assetFromSession}
              title={ps.assetFromSession}
              data-testid={`project-space-asset-jump-${artifact.id}`}
              onClick={() => onOpenSession(artifact.sessionId)}
            />
          ) : null}
        </div>
      ))}
    </div>
  );
};

// ============================================================================
// ProjectComposer —— 协作空间底部输入框。
// 直接复用主聊天 ChatInput 完整件（爸 2026-07-30 拍板「把外面的完整输入框搬进来或用同一个」）。
// sessionless 模式 = 主界面新会话草稿同款语义：会话绑定的部件（/loop、记忆开关、资料库 pin、
// 实时通话）按既有草稿态逻辑降级提示，不会绑到项目页背后那个会话上发错配置。
// 发送链路：onSend(envelope) 内 createSession（workingDirectory=项目 workspacePath，host 侧
// ensureProjectForWorkspace 按 workspace 自动挂 projectId）→ 乐观上屏首条用户消息
// （落地即进行中态：切进会话那一刻消息已在时间线上，不再先 stare 几秒空态）
// → pendingProjectChatSeed（完整 envelope，clientMessageId 与乐观消息同 id）
// → switchSession，ChatView 消费 seed 把 envelope 真正发给 agent（sendMessage 按 id 去重
// 不双份）；发送失败 ChatView 侧回滚乐观消息。@neo 前缀原样透传，不特殊处理。
// ============================================================================

import React, { useCallback, useState } from 'react';
import type { Message } from '@shared/contract';
import type { ConversationEnvelope } from '@shared/contract/conversationEnvelope';
import type { Project } from '@shared/contract/project';
import { generateMessageId } from '@shared/utils/id';
import { useProjectChatSeedStore } from '../../../stores/projectChatSeedStore';
import { useSessionStore } from '../../../stores/sessionStore';
import { ChatInput } from '../chat/ChatInput';

export interface ProjectComposerProps {
  project: Project | null;
}

const TITLE_MAX_LENGTH = 30;

export const ProjectComposer: React.FC<ProjectComposerProps> = ({ project }) => {
  const [sending, setSending] = useState(false);

  const handleSend = useCallback(async (envelope: ConversationEnvelope): Promise<boolean> => {
    const content = envelope.content.trim();
    if (!content && !(envelope.attachments?.length)) return false;
    if (sending) return false;
    setSending(true);
    try {
      const titleSource = content || envelope.attachments?.[0]?.name || '';
      const title = titleSource.length > TITLE_MAX_LENGTH ? titleSource.slice(0, TITLE_MAX_LENGTH) : titleSource;
      const session = await useSessionStore.getState().createSession(title || undefined, {
        workingDirectory: project?.workspacePath ?? undefined,
      });
      if (!session) return false;
      // 乐观上屏：createSession 已把 currentSessionId 切到新会话，消息直接进它的时间线。
      const userMessage: Message = {
        id: envelope.clientMessageId ?? generateMessageId(),
        role: 'user',
        content: envelope.content,
        timestamp: Date.now(),
        ...(envelope.attachments?.length ? { attachments: envelope.attachments } : {}),
      };
      useSessionStore.getState().addMessage(userMessage);
      useProjectChatSeedStore.getState().setPendingProjectChatSeed({
        sessionId: session.id,
        envelope: { ...envelope, clientMessageId: userMessage.id },
      });
      // switchSession 会 closeSecondaryPages()，本页让位给新会话；ChatView 消费 seed 发出首条消息
      await useSessionStore.getState().switchSession(session.id);
      return true;
    } finally {
      setSending(false);
    }
  }, [project?.workspacePath, sending]);

  return (
    <div className="shrink-0 border-t border-zinc-800/70" data-testid="project-space-composer">
      <ChatInput onSend={handleSend} disabled={sending} sessionless />
    </div>
  );
};
// ============================================================================
// ProjectConfigCard —— 项目配置右栏的通用卡片（专家/技能/连接器/自动化共用）。
// 结构：标题 +「+」+ 已选 chip 列表（每个带移除 ×）+「添加」弹窗（搜索 + 两行列表项）。
// 交互（批P 审美关 2026-07-30）：
// - 整卡可点打开添加弹窗：role=button + tabIndex + Enter/Space 键盘可达；
//   卡内「+」与 chip 删除 × 各自 stopPropagation，点它们不触发卡面点击。
// - 弹窗顶部搜索框本地过滤（名称+描述都搜）；列表项两行 = 名称 + 描述，描述空则单行降级。
// - 只读卡（如技能在非本项目工作目录）整卡不可点，「+」禁用态 + tooltip 说明原因
//   （房规：能力不可用要降级提示，不是消失），hint 不进卡身，避免卡高不齐。
// ============================================================================

import React, { useMemo, useState } from 'react';
import { Plus, Search, X } from 'lucide-react';
import { Badge } from '../../primitives/Badge';
import { IconButton } from '../../primitives/IconButton';
import { Input } from '../../primitives/Input';
import { Modal } from '../../primitives/Modal';
import { RoleIcon } from '../shared/RoleIcon';

interface ConfigCardItem {
  id: string;
  label: string;
  /** 弹窗列表项第二行（描述）；空则单行降级（连接器无描述字段，只列 label） */
  description?: string;
  /** 列表项左图标（专家：RolePanelEntry.icon 的 lucide 名，缺省 RoleIcon 自兜底） */
  icon?: string;
  /** 专家行首段「花名 · 职能」的职能段（真源=RolePanelEntry.profession，缺省回落分类中文标签；都没有则不显示） */
  profession?: string;
}

export interface ProjectConfigCardProps {
  testId: string;
  title: string;
  addLabel: string;
  removeLabel: string;
  selectedEmptyLabel: string;
  pickerEmptyLabel: string;
  pickerSearchPlaceholder: string;
  pickerNoMatchLabel: string;
  selected: ConfigCardItem[];
  options: ConfigCardItem[];
  onSelect: (id: string) => void;
  /** 省略 = 只读（整卡不可点，「+」禁用态 + title 说明原因） */
  onRemove?: (id: string) => void;
  /** 只读原因：用作「+」禁用态的 title/tooltip（不进卡身，避免四卡高度不齐） */
  readOnlyHint?: string | null;
  /**
   * 列表行图标槽永远渲染（行模板统一：缺 icon 也由 RoleIcon 兜底 UserCircle，行缩进/结构不塌）。
   * RoleIcon 是专家语义图标，仅专家卡开启；技能/连接器/自动化不传 = 保持无图标槽的既有形态。
   */
  showOptionIcons?: boolean;
}
